def get_max_triples(n):
    def a(i):
        return i * i - i + 1

    count = 0
    values = [a(i) for i in range(1, n + 1)]

    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (values[i] + values[j] + values[k]) % 3 == 0:
                    count += 1

    return count

